@mark.asyncio
async def test_zero_x_swapper_build_transactions_data_with_approval(
    zero_x_api_client: ZeroXApiClient,
    zero_x_swapper: ZeroXSwapper,
    chain: Chain,
    investment_parameters: InvestmentParameters,
):
    chain.is_native_token.return_value = False
    zero_x_api_client.get_price.return_value = Price(
        issues=Issues(
            allowance=Allowance(spender="0x2170ed0880ac9a755fd29b2688956bd959f933f8")
        ),
        sellAmount="254516995428172740",
        buyAmount="1000000000000000000",
        buyToken=bnb_token.address,
        sellToken=eth_token.address,
        fees=Fees(),
    )

    zero_x_api_client.get_quote.return_value = QuoteResult(
        root=Quote(
            liquidityAvailable=True,
            permit2=None,
            transaction=Transaction(
                to="0x779a74436eda060911b2c4f209d34ea155f3df09",
                data="",
                gas="322930",
                gasPrice="100000000",
                value="1000000000000000000",
            ),
            sellAmount="254516995428172740",
            sellToken=eth_token.address,
            buyAmount="1000000000000000000",
            buyToken=bnb_token.address,
            fees=Fees(
                integratorFee=None,
                zeroExFee=Fee(
                    amount="382349016667264",
                    token="0x2170ed0880ac9a755fd29b2688956bd959f933f8",
                    type="volume",
                ),
                gasFee=None,
            ),
        )
    )

    transactions_data = await zero_x_swapper.build_transactions(
        order=Order(
            id="2",
            buy_balance=BalanceAtomic(
                asset=bnb_token,
                amount=Decimal(1),
                amount_atomic=1 * 10**18,
                decimals=18,
            ),
            sell_balance=BalanceAtomic(
                asset=eth_token,
                amount=Decimal(0.2),
                amount_atomic=int(0.2 * 10**18),
                decimals=18,
            ),
            type="SELL",
            asset_type="TOKEN",
            tries=[],
            created_at=1234567890,
            status="PENDING",
            trigger="MANUAL",
            buy_basket_id=None,
            sell_basket_id=None,
        ),
        investment_parameters=investment_parameters,
    )

    assert len(transactions_data) == 2

    assert transactions_data[0].type == "SIGN"
    assert transactions_data[0].amount == 0
    assert transactions_data[0].to_address == eth_token.address
    assert transactions_data[0].encoded_input is not None

    assert transactions_data[1].type == "SEND"


@mark.asyncio
async def test_zero_x_swapper_convert_balance_to_token_swap_validation_failed(
    zero_x_api_client: ZeroXApiClient,
    zero_x_swapper: ZeroXSwapper,
    chain: Chain,
):
    chain.is_native_token.return_value = False
    chain.get_token_decimals.return_value = 10
    zero_x_api_client.get_price.side_effect = SwapValidationFailed()

    exchange_converted_balance = await zero_x_swapper.convert_balance_to_token(
        balance=BalanceAtomic(
            asset=bnb_token, amount=Decimal(1), amount_atomic=1 * 10**18, decimals=18
        ),
        token=eth_token,
        investment_parameters=InvestmentParameters(
            slippage_tolerance_in_percentage=Decimal("1"),
        ),
    )

    assert exchange_converted_balance == ExchangeConvertedBalance(
        sell_balance=BalanceAtomic(
            asset=bnb_token, amount=Decimal(1), amount_atomic=1 * 10**18, decimals=18
        ),
        buy_balance=BalanceAtomic(
            asset=eth_token,
            amount=Decimal("0"),
            amount_atomic=0,
            decimals=10,
        ),
    )

    chain.get_token_decimals.assert_awaited_once_with(eth_token.address)
